package io.embodit.signhands.domain

import java.io.File

/** The real asl_letters.json (generated by tools/bake_hands.py); unit tests run in the module directory. */
object TestBook {
    val book: LetterBook by lazy { LetterBook.parse(File("src/main/assets/asl_letters.json").readText()) }

    val head = V3(0f, 1.6f, 0f)

    /** The scene's path: a fake hand at the teaching spot, the practice frame from head to wrist. */
    fun features(fake: FakeHand, handed: Handed, frame: Long = 0L, headYaw: Float = 0f): Features {
        val headPractice = PracticeFrame(head, headYaw)
        val spot = headPractice.toSpace(Layout.sided(Layout.TEACHING_SPOT, handed) + fake.offset)
        val p = PracticeFrame(head, yawOf(V3(spot.x - head.x, 0f, spot.z - head.z)))
        val joints = fake.joints(book, p, handed, frame)
        val w = joints[J.WRIST]
        val practice = PracticeFrame(head, yawOf(V3(w.x - head.x, 0f, w.z - head.z)))
        return HandMath.features(joints, handed, practice, HandMath.handLength(HandMath.rightLocal(joints, HandFrame.of(joints, handed)!!, handed)))!!
    }

    /** One frame the way SignScene.judgeFrame does it (head yaw 0): features, verdict, the followed point. */
    fun judgeFrame(judge: Judge, joints: List<V3>, handed: Handed, ms: Long, headYaw: Float = 0f): Boolean {
        val w = joints[J.WRIST]
        val practice = PracticeFrame(head, yawOf(V3(w.x - head.x, 0f, w.z - head.z)))
        val f = HandMath.features(joints, handed, practice) ?: return false
        val point = HandMath.trackPoint(joints, judge.target.track, PracticeFrame(head, headYaw), handed)
        return judge.push(ms, judge.frame(f), point)
    }
}
